#!/usr/bin/env bash
# Generated by testing/render-graders.sh from validate.sh. Do not edit by hand.
# Run by astrona test after the reference solution: wait, with a timeout,
# until the cluster settles and every outcome passes.
# Runs on the lab VM as the astrona account (astrona pipes it into bash).

# >>> shared checks >>>
LAB_NAME=ats-032-lab-040-03-03
LAB_CONTEXT="kubernetes-admin@astro-$LAB_NAME"
NODE=controlplane
NAMESPACE=starfleet-032-040-03-03
BASELINE=/etc/astrona-lab/etcd-restore.env
OUTCOMES="etcd-on-restored-data roster-restored later-change-gone"

kube() {
  sudo -n kubectl --kubeconfig /etc/kubernetes/admin.conf --request-timeout=15s "$@" </dev/null
}

# The bootstrap writes the UID of the ConfigMap fleet-roster at snapshot time
# to a root-only file on the host, because the restore rolls the cluster back.
baseline() {
  sudo -n sed -n "s/^$1=//p" "$BASELINE" 2>/dev/null
}

# Context guard: the graders only read this VM's own cluster.
lab_guard() {
  local context
  if ! sudo -n test -r /etc/kubernetes/admin.conf; then
    echo "FAIL: guard: /etc/kubernetes/admin.conf is missing, so this is not the lab VM or kubeadm init did not run"
    return 1
  fi
  context=$(sudo -n kubectl --kubeconfig /etc/kubernetes/admin.conf config current-context 2>/dev/null </dev/null) || context=""
  if [ "$context" != "$LAB_CONTEXT" ]; then
    echo "FAIL: guard: admin.conf context is '$context', expected '$LAB_CONTEXT'"
    return 1
  fi
}

# The host directory that the etcd static Pod manifest mounts at its --data-dir.
manifest_data_host_path() {
  sudo -n awk '
    /--data-dir=/ { sub(/.*--data-dir=/, ""); datadir = $0 }
    /^ *- *hostPath:/ || /^ *hostPath:/ { inhost = 1 }
    inhost && /^ *path:/ { path = $2; inhost = 0 }
    /^ *name:/ && path != "" { volume[$2] = path; path = "" }
    /mountPath:/ { mount = $NF }
    /^ *name:/ && mount != "" { mounted[$NF] = mount; mount = "" }
    END {
      for (v in mounted) if (mounted[v] == datadir && (v in volume)) { print volume[v]; exit }
    }' /etc/kubernetes/manifests/etcd.yaml 2>/dev/null
}

check_etcd_on_restored_data() {
  local host_path
  host_path=$(manifest_data_host_path)
  if [ -z "$host_path" ]; then
    echo "FAIL: etcd-on-restored-data: cannot find the hostPath volume that the etcd manifest mounts at its --data-dir"
    return 1
  fi
  if [ "$host_path" = "/var/lib/etcd" ] || [ "$host_path" = "/var/lib/etcd/" ]; then
    echo "FAIL: etcd-on-restored-data: the etcd manifest still mounts /var/lib/etcd; point the etcd-data hostPath at the restored data directory"
    return 1
  fi
  if ! sudo -n test -f "$host_path/member/snap/db"; then
    echo "FAIL: etcd-on-restored-data: $host_path has no member/snap/db, so it is not a restored etcd data directory"
    return 1
  fi
  if ! sudo -n etcdctl --endpoints=https://127.0.0.1:2379 --cacert=/etc/kubernetes/pki/etcd/ca.crt \
      --cert=/etc/kubernetes/pki/etcd/server.crt --key=/etc/kubernetes/pki/etcd/server.key \
      --command-timeout=10s endpoint health >/dev/null 2>&1; then
    echo "FAIL: etcd-on-restored-data: etcd at https://127.0.0.1:2379 is not healthy"
    return 1
  fi
  echo "PASS: etcd-on-restored-data: etcd is healthy and its manifest mounts the restored data directory $host_path"
}

check_roster_restored() {
  local expected uid
  expected=$(baseline roster-uid)
  if [ -z "$expected" ]; then
    echo "FAIL: roster-restored: the baseline file $BASELINE is missing; do not delete it"
    return 1
  fi
  uid=$(kube -n "$NAMESPACE" get configmap fleet-roster -o jsonpath='{.metadata.uid}' 2>/dev/null) || uid=""
  if [ -z "$uid" ]; then
    echo "FAIL: roster-restored: the ConfigMap fleet-roster in $NAMESPACE does not exist; restore it from the snapshot"
    return 1
  fi
  if [ "$uid" != "$expected" ]; then
    echo "FAIL: roster-restored: the ConfigMap fleet-roster has UID $uid, not the UID from the snapshot; restore it, do not create it again"
    return 1
  fi
  echo "PASS: roster-restored: the ConfigMap fleet-roster from the snapshot is back"
}

check_later_change_gone() {
  local output
  if ! output=$(kube -n "$NAMESPACE" get configmap course-correction -o name 2>&1); then
    case "$output" in
      *NotFound*|*"not found"*)
        echo "PASS: later-change-gone: the ConfigMap course-correction, created after the snapshot, is gone"
        return 0 ;;
    esac
    echo "FAIL: later-change-gone: the API server did not answer: $output"
    return 1
  fi
  echo "FAIL: later-change-gone: the ConfigMap course-correction, created after the snapshot, still exists; the cluster does not run on the snapshot data"
  return 1
}

grade() {
  lab_guard || return 1
  case "$1" in
    etcd-on-restored-data) check_etcd_on_restored_data ;;
    roster-restored) check_roster_restored ;;
    later-change-gone) check_later_change_gone ;;
    *) echo "FAIL: Unknown outcome '$1'"; return 1 ;;
  esac
}
# <<< shared checks <<<

main() {
  local attempt outcome output all_passed
  for attempt in $(seq 1 60); do
    all_passed=true
    output=""
    for outcome in $OUTCOMES; do
      output+="$(grade "$outcome")"'
' || all_passed=false
    done
    if $all_passed; then
      printf '%s' "$output"
      echo "PASS: the reference solution settled (attempt $attempt)"
      return 0
    fi
    sleep 5
  done
  printf '%s' "$output"
  echo "FAIL: the reference solution did not pass within five minutes"
  return 1
}

main
